const norm=s=>(s||'').trim().toUpperCase();
// unidade do produto: alça e cadarço são sempre METRO (mt); todo o resto é KG.
// olha o código E a descrição cadastrada, então funciona mesmo passando só o código.
// unidade do produto: usa a UNIDADE CADASTRADA no produto (aba Produtos/Valores).
// Se o produto não tem unidade cadastrada, o padrão é KG.
function normUnit(u){
  u=String(u||'').toUpperCase().trim();
  if(u==='M'||u==='MT'||u==='MTS'||u==='METRO'||u==='METROS'||u==='ML')return 'MT';
  if(u==='U'||u==='UN'||u==='UND'||u==='UNID'||u==='UNIDADE'||u==='PC'||u==='PÇ')return 'UN';
  if(u==='KG'||u==='KGS'||u==='K'||u==='QUILO'||u==='QUILOS')return 'KG';
  return '';
}
function unitOfReal(prOrDesc){
  try{
    // extrai o código, seja objeto de vaga {pr}, código puro, ou string
    var cod='';var uVaga='';
    if(prOrDesc&&typeof prOrDesc==='object'){cod=String(prOrDesc.pr||prOrDesc.codigo||'');uVaga=String(prOrDesc.u||'');}
    else{cod=String(prOrDesc||'');}
    cod=cod.toUpperCase().replace(/\s+/g,'').trim(); // remove TODOS os espaços
    if(!cod)return 'KG';
    // 1) procura a unidade cadastrada no VL (cadastro de produtos) — tem prioridade
    if(typeof VL!=='undefined'&&Array.isArray(VL)){
      var reg=VL.find(function(v){return String(v.codigo||'').toUpperCase().replace(/\s+/g,'')===cod;});
      if(reg&&reg.un){var u=(typeof normUnit==='function')?normUnit(reg.un):String(reg.un).toUpperCase().trim();if(u==='KG'||u==='MT'||u==='UN')return u;}
    }
    // 2) sem cadastro: se a vaga tem unidade salva (dado antigo tipo 'M'), normaliza
    if(uVaga&&typeof normUnit==='function'){var u2=normUnit(uVaga);if(u2==='MT'||u2==='UN')return u2;}
    return 'KG'; // padrão: sem nada = kg
  }catch(e){return 'KG';}
}
window.unitOfReal=unitOfReal;
const fmt=n=>{const v=Number(n)||0;return Number.isInteger(v)?v.toLocaleString('pt-BR'):v.toLocaleString('pt-BR',{maximumFractionDigits:2});};
const money=n=>(Number(n)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
