function render(id){({'v-home':renderHome,'v-board':renderBoard,'v-mov':renderMov,'v-stock':renderStock,'v-recic':(typeof renderRecic==='function'?renderRecic:function(){}),'v-transf':renderTransf,'v-labels':renderLabels,'v-abc':renderABC,'v-values':renderValues,'v-users':renderUsers,'v-act':renderAct,'v-protheus':(typeof renderProtheus==='function'?renderProtheus:function(){})}[id]||(()=>{}))();}

/* ===================== RECICLADORA - 91 (espelho do Chão da expedição) ===================== */
/* Painel IDÊNTICO ao Chão expedição (bipe Entrada/Saída, câmera, contador, totais por código,
   último bipe, zerar código, limpar chão), usando EXATAMENTE os mesmos dados e as mesmas
   funções globais (window.floorAdd / floorSaida / floorRemoveCode / floorClear). Só muda o título. */
/* Recicladora 91: armazenamento fisico independente da Expedicao 71. */
var RECIC=(function(){try{return JSON.parse(localStorage.getItem('wmsx_recic_floor')||'{}')||{};}catch(e){return {};}})();
function _recSave(){try{localStorage.setItem('wmsx_recic_floor',JSON.stringify(RECIC));}catch(e){try{toast('Não foi possível salvar a Recicladora.',false);}catch(_e){}}}
window.recicGetState=function(){return RECIC;};
function _recHas(et){et=_recEt(et);return Object.values(RECIC).some(function(g){return _recEtList(g).some(function(x){return x.et===et;});});}
window.recicHasEt=_recHas;
window.recicAdd=async function(v){
  try{if(typeof window.cleanScanCode==='function')v=window.cleanScanCode(v);}catch(e){}
  var et=_recEt(v);if(!et)return false;
  try{var onde=typeof window.wmsLocalDaEtiqueta==='function'?window.wmsLocalDaEtiqueta(et):null;if(onde){toast('Etiqueta '+et+' já está em '+onde.local+(onde.detalhe?' ('+onde.detalhe+')':'')+'. Faça a SAÍDA antes de dar ENTRADA na Recicladora - 91.',false);return false;}}catch(e){}
  var b=(typeof BOB!=='undefined'&&BOB[et])||null;
  try{if(!b&&typeof window.etqLookup==='function')b=window.etqLookup(et);if(!b&&typeof bobFetch==='function')b=await bobFetch(et);}catch(e){}
  if(!b){toast('Etiqueta '+et+' não está no catálogo',false);return false;}
  if(_recHas(et)){toast('Etiqueta '+et+' já está na Recicladora - 91',false);return false;}
  var pr=b.pr||'—',pl=Number(b.pl)||0,g=RECIC[pr];
  if(!g)g=RECIC[pr]={pr:pr,desc:b.desc||'',qtd:0,kg:0,ets:[],at:nowISO(),by:session?session.u:''};
  g.ets=_recEtList(g);g.ets.unshift({et:et,pl:pl});g.qtd=g.ets.length;g.kg=g.ets.reduce(function(s,x){return s+(Number(x.pl)||0);},0);g.at=nowISO();g.by=session?session.u:'';_recSave();
  try{var m={id:uid(),action:'entrada',w:cfg.warehouse,code:'RECICLADORA',pr:pr,q:pl,u:(typeof unitOf==='function'?unitOf(pr):'KG'),et:et,before:0,after:pl,at:g.at,by:session?session.u:''};MV.unshift(m);if(typeof syncMov==='function')syncMov(m);if(typeof persistDebounced==='function')persistDebounced('mv');}catch(e){}
  try{if(typeof logAct==='function')logAct('recicladora',et+' · '+pr+' · entrada');}catch(e){}toast('+1 na Recicladora - 91 · '+pr);return true;
};
window.recicSaida=function(v){
  var et=_recEt(v),pr='',pl=0,achou=false;
  Object.keys(RECIC).some(function(k){var g=RECIC[k],a=_recEtList(g),x=a.find(function(i){return i.et===et;});if(!x)return false;pr=k;pl=Number(x.pl)||0;g.ets=a.filter(function(i){return i.et!==et;});if(!g.ets.length)delete RECIC[k];else{g.qtd=g.ets.length;g.kg=g.ets.reduce(function(s,i){return s+(Number(i.pl)||0);},0);g.at=nowISO();}achou=true;return true;});
  if(!achou){toast('Etiqueta '+et+' não está na Recicladora - 91',false);return false;}_recSave();
  try{var m={id:uid(),action:'saida',w:cfg.warehouse,code:'RECICLADORA',pr:pr,q:pl,u:(typeof unitOf==='function'?unitOf(pr):'KG'),et:et,before:pl,after:0,at:nowISO(),by:session?session.u:''};MV.unshift(m);if(typeof syncMov==='function')syncMov(m);if(typeof persistDebounced==='function')persistDebounced('mv');}catch(e){}
  try{if(typeof logAct==='function')logAct('recicladora',et+' · '+pr+' · saída');}catch(e){}toast('Saída da Recicladora - 91 · '+et);return true;
};
window.recicRemoveCode=function(pr){if(!(typeof isStrictAdmin==='function'&&isStrictAdmin())){toast('Somente admin pode zerar',false);return;}var g=RECIC[pr];if(!g)return;_recEtList(g).map(function(x){return x.et;}).forEach(function(et){window.recicSaida(et);});renderRecic();};
window.recicClear=function(){if(!(typeof isSuper==='function'&&isSuper())){toast('Somente admin pode limpar',false);return;}if(!confirm('Limpar TODA a Recicladora - 91?'))return;var ets=[];Object.values(RECIC).forEach(function(g){_recEtList(g).forEach(function(x){ets.push(x.et);});});ets.forEach(function(et){window.recicSaida(et);});renderRecic();};
window._recScanMode=window._recScanMode||'add';
function _recEt(s){return String(s==null?'':s).trim().toUpperCase();}
function _recEtList(g){return (g.ets||[]).map(function(x){var et=(typeof x==='string')?_recEt(x):_recEt(x.et);var plg=(typeof x==='string')?0:x.pl;return {et:et,pl:(typeof window.chaoPlReal==='function'?window.chaoPlReal(et,plg):(Number(plg)||0))};});}
/* O saldo da Recicladora é reconstruído pelo último movimento de cada etiqueta.
   Assim todos os aparelhos mostram o mesmo estoque, usando a tabela movimentos
   que já é sincronizada em tempo real, sem criar uma segunda fonte de verdade. */
function _recSyncFromMovs(){
  try{
    if(!Array.isArray(MV)||!MV.length)return false;
    var vistos={},novo={};
    MV.slice().sort(function(a,b){return String(b.at||'').localeCompare(String(a.at||''));}).forEach(function(m){
      var et=_recEt(m&&m.et);if(!et||vistos[et])return;vistos[et]=1;
      if(String(m.code||'').trim().toUpperCase()!=='RECICLADORA'||String(m.action||'').trim().toLowerCase()!=='entrada')return;
      var b=(typeof BOB!=='undefined'&&BOB[et])||null,pr=m.pr||(b&&b.pr)||'SEM CODIGO';
      var pl=Number(m.q)||Number(b&&b.pl)||0,g=novo[pr];
      if(!g)g=novo[pr]={pr:pr,desc:(b&&b.desc)||(typeof descOf==='function'?descOf(pr):'')||'',qtd:0,kg:0,ets:[],at:m.at||'',by:m.by||''};
      g.ets.push({et:et,pl:pl});g.qtd++;g.kg+=pl;
      if(String(m.at||'')>String(g.at||'')){g.at=m.at||g.at;g.by=m.by||g.by;}
    });
    var antes=JSON.stringify(RECIC),depois=JSON.stringify(novo);
    if(antes!==depois){RECIC=novo;_recSave();return true;}
  }catch(e){}
  return false;
}
window.recicSyncFromMovs=_recSyncFromMovs;
function _recTotals(){
  var st=(typeof window.recicGetState==='function')?window.recicGetState():{};var q=0,kg=0,codes=0;
  Object.values(st||{}).forEach(function(g){q+=g.qtd||0;kg+=_recEtList(g).reduce(function(s,x){return s+(Number(x.pl)||0);},0);codes++;});
  return {q:q,kg:kg,codes:codes};
}
function renderRecic(){
  var v=document.getElementById('v-recic');if(!v)return;
  _recSyncFromMovs();
  var t=_recTotals();
  var sup=(typeof isSuper==='function'&&isSuper());
  v.innerHTML='<div class="ph-head"><div><p class="eb">Operação · contagem</p><h1>Recicladora - 91</h1></div>'
    +(t.q?'<div class="actions"><button class="gbtn" id="recExport">'+(ICONS.down||'')+' Exportar</button>'+(sup?'<button class="gbtn" id="recClear">'+(ICONS.reload||'')+' Limpar chão</button>':'')+'</div>':'')
    +'</div>'
    +'<div class="two">'
      +'<div class="panel"><div class="ph" style="display:flex;align-items:center;justify-content:space-between"><span><span class="pdot"></span>Bipar etiqueta</span>'
        +'<span class="modeSeg" id="recModeSeg"><button type="button" data-mode="add">Entrada</button><button type="button" data-mode="out">Saída</button></span></div>'
        +'<label class="fld"><span class="lab" id="recScanLab">Etiqueta (T…)</span><input class="input code" id="recScan" placeholder="ex: T40364663"></label>'
        +'<p id="recScanHint" style="color:var(--muted);font-size:.8rem;margin:0;line-height:1.5">Cada bipe soma <b>+1 bobina</b> e o <b>peso</b> no código. Bipou outra etiqueta do <b>mesmo código</b>? Acumula tudo junto. A mesma etiqueta não conta duas vezes.</p></div>'
      +'<div class="panel" style="display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center">'
        +'<div style="font-family:var(--disp);font-size:3rem;font-weight:800;line-height:1">'+t.q+'</div>'
        +'<div style="font-size:.6rem;letter-spacing:1px;text-transform:uppercase;color:var(--muted);font-weight:700;margin-top:4px">bobinas no chão</div>'
        +(t.q?'<div style="font-family:var(--mono);font-size:.85rem;color:var(--muted);margin-top:8px">'+fmt(t.kg)+' kg · '+t.codes+' '+(t.codes===1?'código':'códigos')+'</div>':'')
      +'</div>'
    +'</div><h3 class="sub">Totais por código</h3><div id="recList"></div>';
  var sc=document.getElementById('recScan');
  if(sc){
    var _mode=function(){return (window._recScanMode==='out')?window.recicSaida:window.recicAdd;};
    var _run=function(val){try{var r=_mode()(val);if(r&&typeof r.then==='function'){r.then(function(){renderRecic();});}else{renderRecic();}}catch(e){renderRecic();}};
    sc.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();_run(sc.value);sc.value='';}});
    sc.placeholder=sup?'bipe ou digite':'toque para bipar';
    try{if(typeof scanLock==='function')scanLock(sc);}catch(e){}
    try{if(window.addCam)addCam('recScan',{continuous:true,onResult:function(val){_run(val);},title:'Escanear bobinas'});}catch(e){}
  }
  /* seletor Entrada/Saída */
  (function(){var seg=document.getElementById('recModeSeg');if(!seg)return;window._recScanMode=window._recScanMode||'add';
    seg.querySelectorAll('button').forEach(function(b){b.classList.toggle('on',b.dataset.mode===window._recScanMode);b.onclick=function(){window._recScanMode=b.dataset.mode;seg.querySelectorAll('button').forEach(function(x){x.classList.toggle('on',x===b);});
      var hint=document.getElementById('recScanHint');var lab=document.getElementById('recScanLab');var inp=document.getElementById('recScan');
      if(window._recScanMode==='out'){if(hint)hint.innerHTML='Modo <b style="color:#dc2626">SAÍDA</b>: cada bipe <b>remove</b> aquela bobina do chão e registra a saída no histórico.';if(lab)lab.textContent='Etiqueta que está saindo';if(inp)inp.placeholder='bipe a etiqueta da saída';}
      else{if(hint)hint.innerHTML='Cada bipe soma <b>+1 bobina</b> e o <b>peso</b> no código. A mesma etiqueta não conta duas vezes.';if(lab)lab.textContent='Etiqueta (T…)';if(inp)inp.placeholder=sup?'bipe ou digite':'toque para bipar';}
      if(inp)try{inp.focus();}catch(e){}
    };});
  })();
  var eb=document.getElementById('recExport');if(eb)eb.onclick=function(){if(typeof exportChao==='function')exportChao('rec');};
  var cb=document.getElementById('recClear');if(cb)cb.onclick=function(){if(typeof window.recicClear==='function'){window.recicClear();}renderRecic();};
  renderRecicList(sup);
}
function renderRecicList(sup){
  var el=document.getElementById('recList');if(!el)return;
  var st=(typeof window.recicGetState==='function')?window.recicGetState():{};
  var groups=Object.values(st||{}).sort(function(a,b){return (b.qtd-a.qtd)||(b.kg-a.kg);});
  if(!groups.length){el.innerHTML='<div class="empty"><div class="ei">'+(ICONS.layers||'')+'</div><b>Chão vazio</b><div class="es">Bipe uma etiqueta para começar a contar.</div></div>';return;}
  el.innerHTML=groups.map(function(g){
    var ets=_recEtList(g);
    var kgR=ets.reduce(function(s,x){return s+(Number(x.pl)||0);},0);
    return ''
    +'<div style="background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px 18px;box-shadow:var(--sh-sm);margin-bottom:12px">'
    +'<div style="display:flex;align-items:flex-start;gap:14px;flex-wrap:wrap">'
      +'<div style="flex:1;min-width:200px">'
        +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span class="mono" style="font-weight:800;font-size:1.15rem">'+g.pr+'</span><span class="pill in">'+g.qtd+' bob</span></div>'
        +'<div style="color:var(--ink);font-size:.9rem;margin-top:6px;font-weight:500">'+(g.desc||'—')+'</div>'
        +'<div style="color:var(--faint);font-size:.72rem;margin-top:5px">último bipe '+rel(g.at)+'</div>'
      +'</div>'
      +'<div style="text-align:right;white-space:nowrap"><div style="font-family:var(--disp);font-weight:800;font-size:1.6rem;line-height:1">'+fmt(kgR)+' <span style="font-size:.8rem;color:var(--muted);font-weight:600">kg</span></div></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">'+ets.map(function(x){var adm=typeof isStrictAdmin==='function'&&isStrictAdmin();return '<span class="pill muted" '+(adm?'style="cursor:pointer" data-et="'+x.et+'" title="Tocar para remover esta etiqueta"':'')+'>'+x.et+(adm?' ✕':'')+'</span>';}).join('')+'</div>'
    +((typeof isStrictAdmin==='function'&&isStrictAdmin())?'<div style="display:flex;gap:10px;margin-top:12px"><button class="gbtn" data-rmcode="'+g.pr+'" style="margin-left:auto;color:var(--out)">Zerar código</button></div>':'')
    +'</div>';
  }).join('');
  el.querySelectorAll('[data-et]').forEach(function(b){b.onclick=function(){if(!(typeof isStrictAdmin==='function'&&isStrictAdmin()))return;try{if(typeof window.recicSaida==='function')window.recicSaida(b.dataset.et);}catch(e){}renderRecic();};});
  el.querySelectorAll('[data-rmcode]').forEach(function(b){b.onclick=function(){if(!(typeof isStrictAdmin==='function'&&isStrictAdmin()))return;try{if(typeof window.recicRemoveCode==='function')window.recicRemoveCode(b.dataset.rmcode);}catch(e){}renderRecic();};});
}
