/* ===== ATALHO DE PRODUTIVIDADE: "/" foca a busca da aba ativa ===== */
document.addEventListener('keydown',function(ev){
  try{
    if(ev.key!=='/'||ev.ctrlKey||ev.metaKey||ev.altKey)return;
    var tag=(document.activeElement&&document.activeElement.tagName||'').toLowerCase();
    if(tag==='input'||tag==='textarea'||document.activeElement.isContentEditable)return; /* já digitando */
    var act=document.querySelector('.view.active');if(!act)return;
    var inp=act.querySelector('.search input, input[id$="Search"], input[id$="Find"], input.input[placeholder*="uscar"], input.input[placeholder*="rocurar"], input.input[placeholder*="iltrar"]');
    if(inp){ev.preventDefault();inp.focus();try{inp.select();}catch(e){}}
  }catch(e){}
});

