try{ if(typeof pdfjsLib!=="undefined") pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js"; }catch(e){}

function parseNum(s){ if(s==null) return 0; const n=parseFloat(String(s).replace(/\./g,'').replace(',','.')); return isNaN(n)?0:n; }
function fmtNum(n){ return (n||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}); }
function itemSep(i){ return i.etiqueta ? (i.status==='separado'||i.status==='conferido') : (i.forceDone || (i.qtdNum>0 && i.feito>=i.qtdNum-0.001)); }
function itemDone(i){ if(i.etiqueta) return i.status==='conferido'; if(i.forceDone) return true; const sep=(i.qtdNum>0 && i.feito>=i.qtdNum-0.001); const t=i.tags||[]; return sep && t.length>0 && t.every(x=>x.conf); }

let items = [];          // itens do lote ATIVO
let camTarget = null;    // item alvo quando a camera abre por um item sem etiqueta
