      var _mpC=el.querySelector('#invMaisP');if(_mpC)_mpC.onclick=function(){window._invMaisP+=60;window.renderInv();};
      var _mfC=el.querySelector('#invMaisF');if(_mfC)_mfC.onclick=function(){window._invMaisF+=60;window.renderInv();};
