        +'<div style="color:var(--muted);font-size:.76rem">sistema: '+(spCur.pr?_esc(spCur.pr):'vazia')+(blind?'':(' · '+_fmtq(expC)+' kg'))+'</div></div>'
        +'<div style="text-align:right"><div style="font-family:var(--disp);font-weight:800;font-size:1.5rem;line-height:1">'+_fmtq(sumC)+'<span style="font-size:.75rem;color:var(--muted)"> kg</span></div>'
        +'<div style="font-size:.68rem;color:var(--faint)">'+(bipCur?bipCur.items.length:0)+' bobina(s) bipada(s)</div>'
