 function v5a(x){return Array.isArray(x)?x:[]}function v5o(x){return x&&typeof x==='object'?x:{}}
 function v5proc(t,q,ref,resp){var m=t.indexOf('PORTARIA')>=0?['Documento validado','Gerar etiquetas','Recebimento']:t.indexOf('RECEBIMENTO')>=0?['Bipar e conferir','100% confirmado','Endereçamento']:t.indexOf('ENDEREÇAMENTO')>=0?['Definir posição','Local confirmado','Armazenagem']:t.indexOf('ARMAZENAGEM')>=0?['Guardar material','Vaga ocupada','Separação']:t.indexOf('SEPARAÇÃO')>=0?['Atender requisição','Quantidade separada','Expedição']:['Baixar material','Saída confirmada','Concluído'],status=Number(q)>0?'EM OPERAÇÃO':'SEM FILA';return '<div class="v5Proc"><div class="v5Box"><div class="v5Title">'+t+'</div><div class="v5Body"><div><span>Quantidade atual</span><b>'+q+'</b></div><div><span>Indicador</span><b>'+ref+'</b></div><div><span>Responsável</span><b>'+resp+'</b></div><div><span>Atividade</span><b>'+m[0]+'</b></div><div><span>Critério de saída</span><b>'+m[1]+'</b></div><div><span>Próximo passo</span><b>'+m[2]+'</b></div><div><span>Status ao vivo</span><b style="color:'+(Number(q)>0?'#168447':'#718096')+'">'+status+'</b></div></div></div></div>'}
 function v5link(q,s){return '<div class="v5Link"><div class="v5Arrow"></div><div class="v5Tri"><b>'+q+'</b></div><small>'+s+'</small></div>'}
 window.renderVSMLean=function(){var el=document.getElementById('v-vsm');if(!el)return;try{var eo=v5o(typeof ETQ==='undefined'?{}:ETQ),et=Object.keys(eo).map(function(k){return eo[k]||{}}),stage=v5a(typeof STAGE==='undefined'?[]:STAGE),slots=v5a(typeof S==='undefined'?[]:S),moves=v5a(typeof MV==='undefined'?[]:MV),wh=typeof cfg!=='undefined'&&cfg?cfg.warehouse:null,occ=slots.filter(function(x){return x&&x.o&&(!wh||x.w===wh)}),rec=et.filter(function(x){return x.status==='entrada'}).length,ger=et.filter(function(x){return x.status==='gerada'}).length,docs=Object.keys(v5o(typeof NFS==='undefined'?{}:NFS)).length+Object.keys(v5o(typeof ROMS==='undefined'?{}:ROMS)).length,today=new Date().toDateString(),out=moves.filter(function(x){return x&&x.action==='saida'&&new Date(x.at).toDateString()===today}).length,old=stage.filter(function(x){return x&&x.at&&Date.now()-Date.parse(x.at)>14400000}).length,kg=stage.reduce(function(a,x){return a+(Number(x.pl)||0)},0),pct=et.length?Math.round(rec/et.length*100):0,ocp=slots.length?Math.round(occ.length/slots.length*100):0,lead=old?'> 4 horas':'< 4 horas';el.innerHTML='<div class="v5Head"><div><div style="font-size:.58rem;color:#f05a0b;font-weight:900;letter-spacing:.12em">VALUE STREAM MAPPING · ESTADO ATUAL</div><h1>Mapa do Fluxo de Valor</h1><p>Fluxo de informação e material atualizado pelo WMS.</p></div><div class="v5Live">AO VIVO · '+new Date().toLocaleTimeString('pt-BR')+'</div></div><div class="v5Hint">Arraste horizontalmente para visualizar todo o mapa</div><div class="v5Wrap"><div class="v5Canvas"><div class="v5Info"><div class="v5Plant"><b>FORNECEDORES</b><small>NF-e · romaneios · materiais</small></div><div class="v5Control"><div class="v5CtrlBox">CONTROLE WMS · '+docs+' DOCUMENTOS</div></div><div class="v5Plant"><b>CLIENTE / PRODUÇÃO</b><small>requisições · consumo · expedição</small></div></div><div class="v5Flow">'+v5proc('01 · PORTARIA FISCAL',docs,'documentos','Fiscal')+v5link(ger,'aguarda bipagem')+v5proc('02 · RECEBIMENTO',rec,pct+'% concluído','Recepção')+v5link(stage.length,'estoque intermediário')+v5proc('03 · ENDEREÇAMENTO',stage.length,fmt(kg)+' kg','Armazém')+v5link(old,'espera acima de 4h')+v5proc('04 · ARMAZENAGEM',occ.length,ocp+'% ocupado','Estoque')+v5link(0,'requisições')+v5proc('05 · SEPARAÇÃO',0,'fila atual','Operação')+v5link(out,'saídas de hoje')+v5proc('06 · EXPEDIÇÃO',out,'hoje','Expedição')+'</div><div class="v5Time"><div><b>Entrada de informação</b><small>'+docs+' documentos</small></div><div><b>Conferência</b><small>'+pct+'% recebido</small></div><div><b>Tempo de espera</b><small>'+lead+'</small></div><div><b>Estoque</b><small>'+ocp+'% ocupado</small></div><div><b>Sistema puxado</b><small>requisições da operação</small></div><div><b>Entrega</b><small>'+out+' saídas hoje</small></div></div><div class="v5Totals"><div class="v5Total"><span>Lead time crítico</span><b>'+lead+'</b></div><div class="v5Total"><span>WIP intermediário</span><b>'+stage.length+' volumes</b></div><div class="v5Total"><span>Peso aguardando</span><b>'+fmt(kg)+' kg</b></div><div class="v5Total"><span>Ocupação atual</span><b>'+ocp+'%</b></div></div></div></div>'}catch(e){console.error('VSM Lean 5',e);el.innerHTML='<div style="background:#fff;border:1px solid #ddd;padding:24px;border-radius:14px"><h2>Mapa do Fluxo de Valor</h2><p>Não foi possível carregar os dados: '+String(e&&e.message||e)+'</p></div>'}};
